sp_widget.client_script:
api.controller = function($http, spUtil) {
  var c = this;
  c.selectedFile = null;
  c.profileSysId = '';
  c.uploading = false;

  c.server.get({ action: 'get_profile' }).then(function(response) {
    var result = (response && response.data) || {};
    if (!result.profile_sys_id) {
      spUtil.addErrorMessage(result.error || 'Could not find your student profile.');
      return;
    }
    c.profileSysId = result.profile_sys_id;
  });

  c.onFileSelected = function(files) {
    c.selectedFile = (files && files[0]) || null;
  };

  c.uploadResume = function() {
    if (!c.selectedFile || !c.profileSysId) {
      return;
    }

    c.uploading = true;
    var url = '/api/now/attachment/file' +
      '?table_name=x_2311790_skills_0_student_profile' +
      '&table_sys_id=' + encodeURIComponent(c.profileSysId) +
      '&file_name=' + encodeURIComponent(c.selectedFile.name);

    $http.post(url, c.selectedFile, {
      headers: {
        'Content-Type': c.selectedFile.type || 'application/octet-stream',
        'X-UserToken': window.g_ck
      },
      transformRequest: []
    }).then(function() {
      c.uploading = false;
      c.selectedFile = null;
      spUtil.addInfoMessage('Resume attached to your student profile.');
    }, function(err) {
      c.uploading = false;
      var msg = (err && err.data && err.data.error && err.data.error.message) ||
        'Upload failed. Check attachment permissions on the student profile table.';
      spUtil.addErrorMessage(msg);
    });
  };
};

sp_widget.css:
.skillsync-container {
  max-width: 620px;
  margin: 24px auto;
  padding: 32px;
  background: #fff;
  border: 1px solid #d8e2e8;
  border-radius: 12px;
  box-shadow: 0 4px 14px rgba(17, 75, 95, 0.08);
  text-align: center;
}

.skillsync-title {
  margin: 0 0 8px;
  color: #114b5f;
  font-size: 22px;
  font-weight: 700;
}

.skillsync-text,
.skillsync-note {
  color: #52666d;
}

.skillsync-note {
  margin: 14px 0 0;
  font-size: 13px;
}

sp_widget.script:
(function() {
  data.table = 'x_2311790_skills_0_student_profile';
  data.profile_sys_id = '';
  data.error = '';

  if (!gs.isLoggedIn()) {
    data.error = 'Sign in to upload a resume.';
    return;
  }

  var userId = gs.getUserID();
  var profile = new GlideRecord(data.table);
  profile.addQuery('u_user', userId);
  profile.setLimit(1);
  profile.query();

  if (profile.next()) {
    data.profile_sys_id = profile.getUniqueValue();
  } else {
    // Helps spot cross-scope blocks vs. user mismatch
    var checkAll = new GlideRecord(data.table);
    checkAll.query();
    data.error = 'No profile matched user ' + userId + ' (visible rows: ' + checkAll.getRowCount() + ').';
  }
})();
